import { FilterDataAccessor } from 'domain/Filter/FilterDataAccessor';
import type { FilterDataStructure, FilterForm, Option } from 'models/Filters';

const ZONE_EUR = 'EUR';
const EUROPE_LABEL = 'Europe';

/**
 * Resolves the country filter option from applied filters and BFF data.
 * When {@link FilterForm.zone} is missing, derives the zone via
 * {@link FilterDataAccessor.getZoneByCountry} so nested country maps
 * (`zone → countries`) from the integration contract still resolve.
 */
function resolveCountryOption(
  accessor: FilterDataAccessor,
  dataFilters: FilterDataStructure,
  applied: FilterForm,
): Option | null {
  const country = accessor.getCountry(dataFilters, applied);
  if (country?.label) {
    return country;
  }

  if (!applied.country) {
    return country;
  }

  const zone = accessor.getZoneByCountry(dataFilters, String(applied.country));
  if (!zone?.value) {
    return country;
  }

  return accessor.getCountry(dataFilters, {
    ...applied,
    zone: zone.value,
  });
}

/**
 * Returns the display label for the applied country filter.
 *
 * @param dataFilters - Page filter structure from BFF
 * @param applied - Applied filter form for the current page
 * @returns Country label, or empty string when country cannot be resolved
 *
 * @remarks
 * Maps EUR zone + ABI country to `"Europe"`.
 * Supports both zone-aware lookups and nested country maps without `applied.zone`.
 */
export function getCountryLabel(
  dataFilters: FilterDataStructure,
  applied: FilterForm,
): string {
  if (applied.zone === ZONE_EUR && applied.country === 'ABI') {
    return EUROPE_LABEL;
  }

  const accessor = FilterDataAccessor.getInstance();
  const country = resolveCountryOption(accessor, dataFilters, applied);
  return String(country?.label ?? '');
}

/**
 * Returns the display label for the applied KPI filter.
 *
 * @param dataFilters - Page filter structure from BFF
 * @param applied - Applied filter form for the current page
 * @returns KPI label, or empty string when KPI cannot be resolved
 */
export function getKpiLabel(
  dataFilters: FilterDataStructure,
  applied: FilterForm,
): string {
  const kpi = FilterDataAccessor.getInstance().getKpi(dataFilters, applied);
  return String(kpi?.label ?? '');
}

/**
 * Builds a page title from country and KPI filter labels.
 *
 * @param dataFilters - Page filter structure from BFF
 * @param applied - Applied filter form for the current page
 * @returns `"<Country> <KPI>"`, or empty string when country label is missing
 *
 * @example
 * getPageTitleByKpi(dataFilters, { zone: 'SAZ', country: 'BRA', kpis: 'volume' })
 * // "Brazil Volume"
 */
export function getPageTitleByKpi(
  dataFilters: FilterDataStructure,
  applied: FilterForm,
): string {
  const countryLabel = getCountryLabel(dataFilters, applied);
  if (!countryLabel) {
    return '';
  }

  const kpiLabel = getKpiLabel(dataFilters, applied);

  return `${countryLabel} ${kpiLabel}`;
}
